############################################################ # Header ############################################################ TEXT(beginproblem());
############################################################ # PG Setup Code ############################################################ Context()->variables->add(n=>"Real"); $d = random(2,10); $a = random(1,20); do {$b = random(1,20);} until ($b != $a); $seq1 = List($a, $a+$d, $a+2*$d, $a+3*$d, $a+4*$d); $seq2 = List($b, $b+$d, $b+2*$d, $b+3*$d, $b+4*$d); $formula1 = Formula("$a + $d*n"); $formula2 = Formula("$b + $d*n");
############################################################ # Body ############################################################
BEGIN_PGML Consider the recurrence relation [`a_n = a_{n-1} + [$d]\text{.}`]
END_PGML
############################################################ # Scaffold ############################################################ Scaffold::Begin(numbered => 1,is_open => "correct_or_first_incorrect",can_open => when_previous_correct,);
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML Find the first five terms of the sequence defined by the recurrence relation and initial condition [`a_0 = [$a]\text{.}`]
[_]{$seq1}{25}
END_PGML
Section::End();
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML Find the closed formula for the sequence defined by the recurrence relation and initial condition [`a_0 = [$a]\text{.}`]
[`a_n = `][_]{$formula1}{25}
END_PGML
Section::End();
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML Find the first five terms of another sequence, also defined by the same recurrence relation but this time with initial condition [`a_0 = [$b]\text{.}`]
[_]{$seq2}{25}
END_PGML
Section::End();
############################################################ # Section ############################################################ Section::Begin("");
